examples.code:
prices = {"яблоко": 120, "груша": 90}

for name, price in prices.items():
    print(name, price)

discounted = {name: round(price * 0.9, 2) for name, price in prices.items()}
print(discounted)   # {'яблоко': 108.0, 'груша': 81.0}

a = {1, 2, 3}
b = {3, 4}
print(sorted(a | b))   # [1, 2, 3, 4]
print(sorted(a & b))   # [3]
print(sorted(a - b))   # [1, 2]

words = ["яблоко", "груша", "яблоко"]
counts = {}
for word in words:
    counts[word] = counts.get(word, 0) + 1
print(counts)                       # {'яблоко': 2, 'груша': 1}
print(max(counts, key=counts.get))  # яблоко

